model LabL14Store {
  id    Int                @id @default(autoincrement())
  name  String
  items LabL14Inventory[]
  @@map("lab_l14_stores")
}

model LabL14Inventory {
  id      Int         @id @default(autoincrement())
  storeId Int         @map("store_id")
  sku     String      @db.VarChar(32)
  stock   Int         @default(0)
  store   LabL14Store @relation(fields: [storeId], references: [id])
  // TODO: one row per (store, sku)
  @@map("lab_l14_inventory")
}
